const j = $json;
const numFields = ['tno','tvol','tval','pmin','pmax','py','pf','pl','plc','plp','pc','pcc','pcp'];

if (!j.date || !j.time) {
  throw new Error('Unexpected API response (missing date/time): ' + JSON.stringify(j).slice(0, 300));
}

const out = {
  symbol: $('Config').first().json.symbol,
  date: String(j.date),
  time: String(j.time),
};

for (const k of numFields) {
  const raw = j[k];
  const n = (raw === null || raw === undefined || raw === '') ? NaN : Number(raw);
  if (!Number.isFinite(n)) {
    throw new Error('Invalid or missing field "' + k + '": ' + raw);
  }
  out[k] = n;
}

return { json: out };

const j = $json;

if (!j.isin) {
  throw new Error('Missing isin: ' + JSON.stringify(j).slice(0, 300));
}

// Order must match $1..$32 in the SQL query. s = text, n = number.
const spec = [
  ['isin','s'],
  ['id','n'],
  ['l18','s'],
  ['l30','s'],
  ['base_l18','s'],
  ['base_id','n'],
  ['base_pl','n'],
  ['base_pc','n'],
  ['base_py','n'],
  ['base_pcp','n'],
  ['type','s'],
  ['date_begin','s'],
  ['date_end','s'],
  ['day_remain','n'],
  ['size_contract','n'],
  ['price_strike','n'],
  ['interest_open','n'],
  ['pl','n'],
  ['pc','n'],
  ['py','n'],
  ['pf','n'],
  ['pmin','n'],
  ['pmax','n'],
  ['tno','n'],
  ['tvol','n'],
  ['tval','n'],
  ['nval','n'],
  ['cs','s'],
  ['cs_id','n'],
  ['tmin','n'],
  ['tmax','n'],
  ['time','s']
];

const params = spec.map(([key, type]) => {
  const raw = j[key];
  if (raw === null || raw === undefined || raw === '') return null;
  if (type === 'n') {
    const n = Number(raw);
    return Number.isFinite(n) ? n : null;
  }
  return String(raw);
});

return { json: { params } };
